-- ===================================================================
-- EasyOrange - RAG 知识库种子文档
-- Description: Repeatable Migration - 平台规则类知识文档（金标准评测集引用）
-- Type: DML（可重复执行，ON DUPLICATE KEY UPDATE 保证幂等）
-- 固定 ID（kb-xxxx）：金标准集 eval/golden-set.yaml 的 gold_doc_ids 引用同一批 ID
--
-- 语料规模是有意为之：kb-0001~kb-0005 是评测命中的目标文档，
-- kb-0006~kb-0025 是**同域干扰文档**（也是真实平台规则，不掺杂物）。
-- 没有干扰项时，topK=5 与语料规模同量级，hit@5 恒为 100%，指标失去判别力 ——
-- 干扰项让「检索选没选对」重新变成可测的问题。
-- ===================================================================

START TRANSACTION;

INSERT INTO `eo_knowledge_doc` (
    `id`, `title`, `content`, `source`, `status`,
    `del_flag`, `create_time`, `update_time`
) VALUES
('kb-0001', '平台交易流程', 'EasyOrange 平台交易流程：\n1. 买家浏览商品并下单；\n2. 卖家确认订单后，买家在订单详情页完成付款；\n3. 卖家发货，买家在物流签收后点击确认收货；\n4. 平台在买家确认收货后担保放款给卖家。\n全程平台不接触货物，交易由买卖双方直接完成，平台仅提供担保与纠纷仲裁。', '平台规则', 'PENDING', 0, NOW(), NOW()),
('kb-0002', '退款规则', 'EasyOrange 退款规则：\n1. 卖家未发货前，买家可随时申请全额退款；\n2. 卖家已发货未签收，买家可申请退款，卖家同意后平台拦截物流原路退回；\n3. 签收后 7 天内支持无理由退货，退回商品需保持完好、不影响二次销售；\n4. 商品与描述严重不符或存在质量问题的，买家可发起申诉，平台介入仲裁。\n退款原路退回支付账户，一般 1-3 个工作日到账。', '平台规则', 'PENDING', 0, NOW(), NOW()),
('kb-0003', '运费规则', 'EasyOrange 运费规则：\n1. 默认运费由买家承担，下单页展示预估运费；\n2. 卖家可设置满额包邮（如满 99 元包邮），下单时自动减免；\n3. 无理由退货时，退货运费由买家承担；因商品质量问题或描述不符导致的退货，退货运费由卖家承担；\n4. 运费以商品详情页标注为准，卖家不得在成交后临时加价。', '平台规则', 'PENDING', 0, NOW(), NOW()),
('kb-0004', '信用分规则', 'EasyOrange 信用分规则：\n1. 信用分满分 100，反映用户交易信誉；\n2. 加分项：按时发货、描述相符、及时确认收货、纠纷无责；\n3. 扣分项：超时未发货、虚假描述、恶意退款、纠纷有责；\n4. 等级划分：90 分以上为优质用户（优先展示、更快放款），70-89 分为良好，60-69 分为一般，60 分以下将限制部分交易功能；\n5. 信用分每日更新一次，申诉成功可恢复被扣分数。', '平台规则', 'PENDING', 0, NOW(), NOW()),
('kb-0005', '禁售品类与可售范围', 'EasyOrange 禁售品类：\n1. 法律法规禁止交易的物品（毒品、枪支弹药、管制刀具、假币等）一律禁售；\n2. 烟酒、处方药、医疗器械等特许经营商品禁售；\n3. 虚拟物品仅限话费充值、游戏点卡等平台白名单品类；\n4. 二手手机、数码、书籍、服饰等个人闲置物品可正常发布，但需如实描述成色与瑕疵；\n5. 违规发布将下架商品并视情节扣信用分。', '平台规则', 'PENDING', 0, NOW(), NOW()),
('kb-0006', '支付方式与支付限额', 'EasyOrange 支付说明：\n1. 支持微信支付、支付宝、银行卡三种渠道；\n2. 单笔支付限额由渠道与风控策略决定，超出限额时页面会提示改用其他渠道；\n3. 支付失败常见原因为余额不足、超出限额、风控拦截，可稍后重试或更换渠道；\n4. 每笔支付均可在订单详情页查看支付流水号与支付时间。', '平台规则', 'PENDING', 0, NOW(), NOW()),
('kb-0007', '发票与交易凭证', 'EasyOrange 凭证说明：\n1. 个人闲置交易默认不开具发票；\n2. 成交后可申请平台电子交易凭证，包含订单编号、成交金额、下单与完成时间；\n3. 企业采购需要发票的，请在成交前联系客服确认可开票范围；\n4. 交易凭证与支付流水可作为售后与仲裁的辅助材料。', '平台规则', 'PENDING', 0, NOW(), NOW()),
('kb-0008', '举报与仲裁流程', 'EasyOrange 举报与仲裁：\n1. 商品详情页与订单页均提供举报入口；\n2. 举报需选择类型并上传举证材料（聊天记录、商品实拍、物流凭证）；\n3. 平台在收到举报后 48 小时内响应，并视情况要求双方补充材料；\n4. 仲裁结论依据举证材料与平台规则作出，双方均可在申诉期内提出异议。', '平台规则', 'PENDING', 0, NOW(), NOW()),
('kb-0009', '商品发布规范', 'EasyOrange 发布规范：\n1. 标题不得堆砌无关关键词或使用夸张宣传词；\n2. 描述需如实反映成色、瑕疵与配件情况；\n3. 禁止使用他人图片或官方宣传图，须为实物拍摄；\n4. 一件商品对应一个发布，重复铺货会被合并或下架。', '平台规则', 'PENDING', 0, NOW(), NOW()),
('kb-0010', '账号安全与实名认证', 'EasyOrange 账号安全：\n1. 发布与提现前需完成实名认证，一人一号；\n2. 异地或异常登录会触发提醒，可通过安全中心查看登录记录；\n3. 账号被盗请立即修改密码并联系客服冻结账号；\n4. 账号禁止买卖、出租或转让，一经发现将限制交易功能。', '平台规则', 'PENDING', 0, NOW(), NOW()),
('kb-0011', '优惠券与平台活动', 'EasyOrange 优惠券说明：\n1. 优惠券可在活动页或任务中心领取，达到使用门槛自动生效；\n2. 每张券有独立有效期，过期作废且不补发；\n3. 除活动特别说明外，优惠券不可与其他券叠加使用；\n4. 下单页展示的到手价已包含可用优惠券的抵扣金额。', '平台规则', 'PENDING', 0, NOW(), NOW()),
('kb-0012', '平台积分规则', 'EasyOrange 积分说明：\n1. 积分通过每日签到、成交、评价等行为获取；\n2. 积分有效期为获取当年年底，过期自动清零；\n3. 积分可在积分商城兑换实物或抵扣部分订单金额；\n4. 通过违规行为获取的积分将被追回。', '平台规则', 'PENDING', 0, NOW(), NOW()),
('kb-0013', '物流时效与签收', 'EasyOrange 物流说明：\n1. 默认发货时限为下单并付款后的 48 小时；\n2. 物流轨迹由快递公司回传，可能存在数小时延迟；\n3. 支持驿站、快递柜等代收点签收，代收即视为送达；\n4. 偏远地区时效顺延，具体以快递公司公示为准。', '平台规则', 'PENDING', 0, NOW(), NOW()),
('kb-0014', '评价规则', 'EasyOrange 评价规则：\n1. 订单完成后评价入口开放，评价期为 30 天；\n2. 评价一经提交不可修改或删除，可在评价后追加一次追评；\n3. 评价内容需与交易相关，含辱骂或泄露隐私的将被折叠；\n4. 以差评要挟额外补偿属于违规行为，可举报处理。', '平台规则', 'PENDING', 0, NOW(), NOW()),
('kb-0015', '售后服务与保修', 'EasyOrange 售后说明：\n1. 闲置物品按“如实描述”原则交易，卖家需对描述的真实性负责；\n2. 数码、家电等商品建议在描述中写明剩余保修期与购买凭证情况；\n3. 保修责任由品牌方或原购买渠道承担，平台不提供额外保修；\n4. 售后沟通建议全程在站内进行，便于举证。', '平台规则', 'PENDING', 0, NOW(), NOW()),
('kb-0016', '违规处罚与申诉', 'EasyOrange 违规处罚：\n1. 违规行为按情节分为轻微、一般、严重三级；\n2. 处罚措施包括警告、商品下架、搜索降权、限制发布与封禁账号；\n3. 受到处罚后可提交申诉材料，申诉期为处罚生效后 7 天；\n4. 处罚记录与申诉结果可在账号中心的违规记录中查看。', '平台规则', 'PENDING', 0, NOW(), NOW()),
('kb-0017', '隐私与个人信息保护', 'EasyOrange 隐私说明：\n1. 平台仅收集交易与服务必需的信息（联系方式、收货地址、实名信息）；\n2. 收货地址与手机号在聊天与订单页对交易对方做脱敏展示；\n3. 未经同意不向第三方提供个人信息，法律法规要求除外；\n4. 注销账号后交易记录依法保留，其余个人信息在保留期后删除。', '平台规则', 'PENDING', 0, NOW(), NOW()),
('kb-0018', '订单取消规则', 'EasyOrange 订单取消：\n1. 下单后未付款的订单将在 30 分钟后自动取消；\n2. 卖家缺货或商品已售出时，卖家可主动取消并说明原因；\n3. 频繁取消或多次因缺货取消会影响卖家账号的曝光权重；\n4. 已付款订单需双方协商一致后取消，款项按原路退回。', '平台规则', 'PENDING', 0, NOW(), NOW()),
('kb-0019', '卖家保证金与缴纳标准', 'EasyOrange 保证金说明：\n1. 高价值品类（数码、奢侈品等）卖家需缴纳保证金后方可发布；\n2. 保证金金额按品类与历史成交情况核定；\n3. 保证金用于承担违规造成的赔付，无违规时可在停止经营后申请退还；\n4. 保证金不足时将限制发布相应品类商品。', '平台规则', 'PENDING', 0, NOW(), NOW()),
('kb-0020', '商品图片与视频规范', 'EasyOrange 图片规范：\n1. 单件商品最多上传 9 张图片，首图须为商品主体实拍；\n2. 图片不得包含水印、二维码、店铺名称或其他联系方式；\n3. 支持上传 1 段时长不超过 60 秒的展示视频；\n4. 图片与实物严重不符将按虚假描述处理。', '平台规则', 'PENDING', 0, NOW(), NOW()),
('kb-0021', '未成年人交易限制', 'EasyOrange 未成年人保护：\n1. 未满 18 周岁的用户需经监护人同意方可进行交易；\n2. 禁止未成年人发布与购买高风险品类商品；\n3. 涉及未成年人的举报将优先处理；\n4. 监护人可提供材料申请关闭相关账号的交易功能。', '平台规则', 'PENDING', 0, NOW(), NOW()),
('kb-0022', '赠品与配件说明', 'EasyOrange 赠品与配件：\n1. 赠品与配件需在商品描述中列明，未列明的不作为成交条件；\n2. 赠品不计入商品成交金额，其缺失不影响主商品的交易履行；\n3. 主商品与描述相符而仅赠品缺失时，买家可与卖家协商补偿；\n4. 配件缺失属于描述不符的情形，买家可依此提出售后请求。', '平台规则', 'PENDING', 0, NOW(), NOW()),
('kb-0023', '进口与海外商品规则', 'EasyOrange 进口商品说明：\n1. 进口商品需在描述中提供合规证明与购买渠道信息；\n2. 关税与清关费用由买家承担的，须在描述中明确标注；\n3. 不支持跨境直邮的商品请勿以海外直邮进行宣传；\n4. 无中文标识的进口商品需提示买家注意。', '平台规则', 'PENDING', 0, NOW(), NOW()),
('kb-0024', '会员等级与权益', 'EasyOrange 会员体系：\n1. 会员等级依据累计成交金额与账号活跃度划分；\n2. 等级越高可享优先展示、专属客服、活动优先报名等权益；\n3. 等级每月初更新一次，权益随等级实时生效；\n4. 会员等级与交易信誉评价相互独立，分别展示。', '平台规则', 'PENDING', 0, NOW(), NOW()),
('kb-0025', '客服渠道与工作时间', 'EasyOrange 客服说明：\n1. 在线客服工作时间为每日 9:00-21:00；\n2. 非工作时间可通过工单提交问题，次工作日按顺序处理；\n3. 涉及资金安全与账号被盗的紧急问题请选择紧急通道；\n4. 常见问题可通过帮助中心的自助指引先行排查。', '平台规则', 'PENDING', 0, NOW(), NOW())
AS new
ON DUPLICATE KEY UPDATE
    `title` = new.`title`,
    `content` = new.`content`,
    `source` = new.`source`,
    `status` = new.`status`,
    `update_time` = new.`update_time`;

COMMIT;
